                         for a in tracks for b in tracks))
    phase = {d % period: color for d, color in tracks.items()}
    # Continue the nearest preceding track color into unobserved phases.
    known = set(phase)
    for k in range(period):
        if k not in phase:
            phase[k] = phase[min(known, key=lambda x: (k - x) % period)]
    return [[phase[(c - r) % period] for c in range(w)] for r in range(h)]
